// WeChat loads JavaScript modules, not Node-style JSON requires.
const fs = require('node:fs');
const path = require('node:path');
const directory = path.resolve(__dirname, '../miniprogram/data');
const config = JSON.parse(fs.readFileSync(path.join(directory, 'location-calibration.json'), 'utf8'));
fs.writeFileSync(path.join(directory, 'location-calibration.js'),
  '// Generated by scripts/sync-calibration.cjs. Edit the JSON source, then resync.\n' +
  'module.exports = ' + JSON.stringify(config, null, 2) + ';\n');
console.log('Synced calibration JavaScript module; enabled:', config.enabled);
